import{_ as t,a as o,o as a,ai as n}from"./chunks/framework.BbOtTPsL.js";const g=JSON.parse('{"title":"Channels","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/channels/index.md","filePath":"api/graphql-api/admin/settings/channels/index.md","lastUpdated":1782473079000}'),d={name:"api/graphql-api/admin/settings/channels/index.md"};function c(s,e,r,i,l,h){return a(),o("div",null,e[0]||(e[0]=[n('<h1 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h1><p>A <strong>channel</strong> is a storefront. Each channel is a self-contained shopping front with its own hostname/domain, theme, timezone, default and allowed locales, base and allowed currencies, inventory sources, root category, SEO defaults, and maintenance mode. One store can run several channels at once — for example a US storefront and an EU storefront, each on its own domain with its own currency and language set. This menu mirrors the admin <strong>Settings → Channels</strong> screen.</p><h2 id="what-a-channel-holds" tabindex="-1">What a channel holds <a class="header-anchor" href="#what-a-channel-holds" aria-label="Permalink to &quot;What a channel holds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>code</code></td><td>Unique channel code.</td></tr><tr><td><code>name</code> / <code>description</code></td><td>Display name and description (translatable per locale).</td></tr><tr><td><code>hostname</code></td><td>The domain/URL the channel is served on.</td></tr><tr><td><code>theme</code></td><td>The storefront theme assigned to the channel.</td></tr><tr><td><code>timezone</code></td><td>The channel&#39;s timezone.</td></tr><tr><td><code>defaultLocaleId</code></td><td>The channel&#39;s default language — must be one of the assigned locales.</td></tr><tr><td><code>locales</code></td><td>The languages available on this channel — a connection of locale objects (<code>_id</code> / <code>code</code> / <code>name</code> / <code>direction</code>).</td></tr><tr><td><code>baseCurrencyId</code></td><td>The channel&#39;s base currency — must be one of the assigned currencies.</td></tr><tr><td><code>currencies</code></td><td>The currencies available on this channel — a connection of currency objects (<code>_id</code> / <code>code</code> / <code>name</code> / <code>symbol</code>).</td></tr><tr><td><code>inventorySources</code></td><td>The inventory sources this channel sells from — a connection of source objects (<code>_id</code> / <code>code</code> / <code>name</code> / <code>status</code>).</td></tr><tr><td><code>rootCategoryId</code></td><td>The top category of the channel&#39;s catalog tree.</td></tr><tr><td><code>seoMetaTitle</code> / <code>seoMetaDescription</code> / <code>seoMetaKeywords</code></td><td>The home-page SEO defaults, as flat selectable fields. The whole block is also available as the <code>homeSeo</code> object.</td></tr><tr><td><code>isMaintenanceOn</code> / <code>maintenanceModeText</code></td><td>Whether the storefront is in maintenance mode, and the message shown to visitors while it is.</td></tr><tr><td><code>allowedIps</code></td><td>IP / CIDR strings allowed through while maintenance mode is on (JSON array).</td></tr><tr><td><code>logo</code> / <code>logoUrl</code>, <code>favicon</code> / <code>faviconUrl</code></td><td>Branding images — the stored path and the ready-to-use absolute URL.</td></tr><tr><td><code>translations</code></td><td>Per-locale values for the translatable fields — a connection of translation objects (<code>_id</code> / <code>locale</code> / <code>name</code> / <code>description</code> / <code>maintenanceModeText</code> / <code>homeSeo</code>).</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Reading the assignments</p><p>A channel&#39;s assigned locales, currencies, and inventory sources are exposed as the <code>locales</code> / <code>currencies</code> / <code>inventorySources</code> <strong>object connections</strong>. Read the assigned ids as <code>locales { edges { node { _id } } }</code> (and the same for currencies / inventory sources), alongside each row&#39;s <code>code</code> / <code>name</code> / etc.</p></div><p>The <code>locales</code> / <code>currencies</code> / <code>inventorySources</code> / <code>translations</code> connections are detail-only — they come back empty on listing rows. Fetch a single channel to get them populated, sub-selecting <code>{ edges { node { … } } }</code>.</p><h2 id="how-translatable-fields-work" tabindex="-1">How translatable fields work <a class="header-anchor" href="#how-translatable-fields-work" aria-label="Permalink to &quot;How translatable fields work&quot;">​</a></h2><p>Translatable scalars — <code>name</code>, <code>description</code>, the SEO triplet, and <code>maintenanceModeText</code> — exist once per locale. When you <strong>create</strong> a channel, the top-level values you send are broadcast to every locale you assign, so the new channel comes back with one <code>translations</code> connection node per assigned locale. When you <strong>update</strong>, a top-level scalar edits the channel&#39;s request locale only; other locales keep their previous values.</p><h2 id="creating-updating-and-deleting" tabindex="-1">Creating, updating, and deleting <a class="header-anchor" href="#creating-updating-and-deleting" aria-label="Permalink to &quot;Creating, updating, and deleting&quot;">​</a></h2><ul><li><strong>Create</strong> requires a unique <code>code</code>, non-empty <code>locales</code> / <code>currencies</code> / <code>inventorySources</code> arrays, a <code>defaultLocaleId</code> that is one of the assigned locales, a <code>baseCurrencyId</code> that is one of the assigned currencies, and a <code>rootCategoryId</code>.</li><li><strong>Update</strong> is partial — send only the fields you want to change. <strong>Omitting</strong> the <code>locales</code> / <code>currencies</code> / <code>inventorySources</code> arrays preserves the channel&#39;s existing assignments; <strong>supplying</strong> any of them replaces that set entirely, so always send the full intended set.</li><li><strong>Delete</strong> is guarded: the store refuses to delete the <strong>last remaining channel</strong> and refuses to delete the <strong>default app channel</strong>. Both come back as an <code>errors[]</code> entry. On success the deleted record is returned as a snapshot, so you can select <code>id</code> / <code>_id</code> / <code>code</code> / <code>name</code> to confirm what was removed.</li></ul><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./list.html">List channels</a></td><td><code>adminSettingsChannels</code> query</td></tr><tr><td><a href="./detail.html">Get a single channel</a></td><td><code>adminSettingsChannel(id:)</code> query</td></tr><tr><td><a href="./create.html">Create a channel</a></td><td><code>createAdminSettingsChannel</code> mutation</td></tr><tr><td><a href="./update.html">Update a channel</a></td><td><code>updateAdminSettingsChannel</code> mutation</td></tr><tr><td><a href="./delete.html">Delete a channel</a></td><td><code>deleteAdminSettingsChannel</code> mutation</td></tr></tbody></table><p>Permissions: <code>settings.channels.create</code> / <code>.edit</code> / <code>.delete</code>.</p><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',14)]))}const m=t(d,[["render",c]]);export{g as __pageData,m as default};
